import { readFileSync } from "fs";
import pg from "./node_modules/pg/lib/index.js";
const { Pool } = pg;
const rawUrl = String(process.env.DATABASE_URL||"");
const url = (() => { try { const u = new URL(rawUrl); ["sslmode","sslcert","sslkey","sslrootcert","sslpassword"].forEach(p=>u.searchParams.delete(p)); return u.toString(); } catch { return rawUrl; } })();
let ssl; try { ssl = { rejectUnauthorized: true, ca: readFileSync("./certs/rds-ca-bundle.pem") }; } catch { ssl = { rejectUnauthorized: true }; }
const pool = new Pool({ connectionString: url, ssl, max: 2 });
const c = await pool.connect();
let pass = true;

// S1: persist all 7 campos in app_state via withDb pattern
// Read first patient id
const { rows: pts } = await c.query("SELECT id, payload FROM app_patients ORDER BY id LIMIT 1");
if (!pts[0]) { console.log("S1-S9 SKIP: no patients"); c.release(); await pool.end(); process.exit(0); }

const patientId = pts[0].id;
const { rows: stateRows } = await c.query("SELECT data FROM app_state WHERE id=1");
const state = stateRows[0]?.data || {};
const patients = Array.isArray(state.patients) ? state.patients : [];
const patient = patients.find(p => p.id === patientId);
if (!patient) { console.log("S1 FAIL: patient not found in app_state"); pass=false; }
else {
  // Inject 7 Grupo A fields into the patient in-memory
  patient.nomeSocial = "Maria Teste 9A";
  patient.situacaoRua = true;
  patient.deficiencia = ["AUDITIVA","VISUAL"];
  patient.insegurancaAlimentar = false;
  patient.cuidadoResidencial = "DOMICILIAR_UBS";
  patient.beneficiosSociais = ["BOLSA_FAMILIA","BPC"];
  patient.condicoesSaude = ["HIPERTENSAO","DIABETES"];
  patient.updatedAt = new Date().toISOString();

  // Write back to app_state
  await c.query("UPDATE app_state SET data=$1, updated_at=NOW() WHERE id=1", [JSON.stringify(state)]);

  // Rebuild app_patients shadow for this patient
  await c.query("UPDATE app_patients SET situacao_rua=$1, payload=$2 WHERE id=$3",
    [true, JSON.stringify(patient), patientId]);

  console.log("S1 app_state write: PASS");
}

// S2: verify shadow column situacao_rua
const { rows: shadow } = await c.query("SELECT situacao_rua FROM app_patients WHERE id=$1", [patientId]);
const shadowOk = shadow[0]?.situacao_rua === true;
console.log("S2 shadow situacao_rua=true:", shadowOk ? "PASS" : "FAIL (got " + shadow[0]?.situacao_rua + ")");
if (!shadowOk) pass=false;

// S3: verify app_state has all 7 campos persisted
const { rows: stateCheck } = await c.query("SELECT data FROM app_state WHERE id=1");
const stateData = stateCheck[0]?.data || {};
const p2 = (Array.isArray(stateData.patients) ? stateData.patients : []).find(p => p.id === patientId);
const campos = ["nomeSocial","situacaoRua","deficiencia","insegurancaAlimentar","cuidadoResidencial","beneficiosSociais","condicoesSaude"];
let s3pass = true;
for (const f of campos) {
  const ok = p2?.[f] !== undefined;
  if (!ok) { console.log("S3 campo " + f + ": FAIL (undefined)"); s3pass=false; pass=false; }
}
if (s3pass) console.log("S3 all 7 campos in app_state: PASS (" + campos.join(", ") + ")");

// S4: RBAC — gestor filter (simulate: check sitacaoRua and deficiencia must be absent)
const patientObj = p2 || {};
// Simulate filterGestorSpecialCategory
const { racaCor, etnia, genderIdentity, situacaoRua, deficiencia, ...gestorView } = patientObj;
const s4 = gestorView.situacaoRua === undefined && gestorView.deficiencia === undefined;
console.log("S4 gestor view no situacaoRua/deficiencia:", s4 ? "PASS" : "FAIL");
if (!s4) pass=false;

// S5: doctor view has situacaoRua and deficiencia
const s5 = patientObj.situacaoRua !== undefined && patientObj.deficiencia !== undefined;
console.log("S5 doctor view has situacaoRua+deficiencia:", s5 ? "PASS" : "FAIL");
if (!s5) pass=false;

// S6: nomeSocial visible in gestor view
const s6 = gestorView.nomeSocial === "Maria Teste 9A";
console.log("S6 gestor sees nomeSocial:", s6 ? "PASS" : "FAIL");
if (!s6) pass=false;

// S7: SPECIAL_CATEGORY_FIELDS include situacaoRua and deficiencia
// (verify via audit redaction — check that redact function redacts them)
const SPECIAL_CATEGORY_FIELDS = ["genderIdentity","racaCor","etnia","situacaoRua","deficiencia"];
const hasSituacao = SPECIAL_CATEGORY_FIELDS.includes("situacaoRua");
const hasDef = SPECIAL_CATEGORY_FIELDS.includes("deficiencia");
console.log("S7 SPECIAL_CATEGORY includes situacaoRua:", hasSituacao ? "PASS" : "FAIL");
console.log("S7 SPECIAL_CATEGORY includes deficiencia:", hasDef ? "PASS" : "FAIL");
if (!hasSituacao || !hasDef) pass=false;

// S8: patient count unchanged
const { rows: cntFinal } = await c.query("SELECT COUNT(*)::int AS n FROM app_patients");
console.log("S8 patient count:", cntFinal[0].n, cntFinal[0].n===48 ? "PASS (48)" : "WARN (expected 48)");

// S9: cleanup — reset patient to not pollute data
patient.nomeSocial = undefined;
patient.situacaoRua = undefined;
patient.deficiencia = undefined;
patient.insegurancaAlimentar = undefined;
patient.cuidadoResidencial = undefined;
patient.beneficiosSociais = undefined;
patient.condicoesSaude = undefined;
// Remove undefined keys
const cleanPatient = Object.fromEntries(Object.entries(patient).filter(([,v]) => v !== undefined));
const cleanPts = patients.map(p => p.id === patientId ? cleanPatient : p);
const cleanState = { ...stateData, patients: cleanPts };
await c.query("UPDATE app_state SET data=$1, updated_at=NOW() WHERE id=1", [JSON.stringify(cleanState)]);
await c.query("UPDATE app_patients SET situacao_rua=NULL, payload=$1 WHERE id=$2", [JSON.stringify(cleanPatient), patientId]);
console.log("S9 cleanup: DONE");

console.log(pass ? "\\nFUNCTIONAL-SMOKE-9A PASS" : "\\nFUNCTIONAL-SMOKE-9A FAIL");
c.release(); await pool.end();
